// hosted/scripts/build-icons.mjs
// Rasterise hosted/brand/icon.svg into the icon files the app actually SERVES.
//
// Why this writes to public/ and not hosted/static/
// ----------------------------------------------------
// The old version of this script rendered into `hosted/static/`. That
// directory is in .gitignore and nothing copies it into the build — so the
// pipeline produced a set of icons that were never committed and never
// deployed, while the icons the browser really loads (public/favicon-32.png,
// public/icons/*.png) could only be regenerated by hand. The output went
// nowhere and the input was a placeholder that matched nothing.
//
// hosted/brand/icon.svg is now the single source of truth and this script
// renders it into every location src/app/layout.tsx and
// public/manifest.webmanifest reference. Run it after changing the mark:
//
//     pnpm build:icons
//
// and commit the result — these files ARE tracked, because they ARE served.

import sharp from 'sharp';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

const SOURCE = 'hosted/brand/icon.svg';

/**
 * The maskable variant.
 *
 * A maskable icon is cropped to a circle inscribed in the canvas and the
 * platform may zoom it further, so the mark must sit inside the inner 80%
 * safe zone on a background that fills the WHOLE canvas.
 *
 * The medallion's own background is a ROUNDED SQUARE, so it cannot be the
 * maskable background — the platform crops to a circle and the square's
 * corners are cut away, leaving a visible seam. So the maskable variant is
 * rebuilt from the same source: the background becomes a full-bleed square
 * and the mark is scaled to 80% about the centre, on the same gradient.
 */
const MASKABLE_SCALE = 0.8;

const source = readFileSync(SOURCE, 'utf8');

/** Rebuild the SVG as a full-bleed background with the mark at 80%. */
function maskableMarkup(svg) {
  const bg = /<rect width="512" height="512" rx="112"[^>]*\/>/.exec(svg);
  if (!bg) {
    throw new Error(
      `${SOURCE}: expected a <rect width="512" height="512" rx="112" .../> background to ` +
        `rebuild the maskable icon from. Fix the source rather than this script.`,
    );
  }
  const defs = svg.slice(0, bg.index);
  const mark = svg
    .slice(bg.index + bg[0].length)
    .replace(/<\/svg>\s*$/, '')
    .trim();
  return (
    `${defs}<rect width="512" height="512" fill="url(#bg)"/>\n` +
    `  <g transform="translate(256 256) scale(${MASKABLE_SCALE}) translate(-256 -256)">\n` +
    `    ${mark}\n` +
    `  </g>\n` +
    `</svg>\n`
  );
}

const maskable = maskableMarkup(source);

/** The square icons the layout and the manifest point at. */
const plain = [
  { out: 'public/favicon-16.png', size: 16 },
  { out: 'public/favicon-32.png', size: 32 },
  { out: 'public/icons/icon-192.png', size: 192 },
  { out: 'public/icons/icon-512.png', size: 512 },
  { out: 'public/icons/apple-touch-icon.png', size: 180 },
];

/** Maskable icons: the mark at 80%, centred, on a full-bleed ink background. */
const maskables = [
  { out: 'public/icons/maskable-192.png', size: 192 },
  { out: 'public/icons/maskable-512.png', size: 512 },
];

mkdirSync('public/icons', { recursive: true });

// The SVG the browser loads directly (and the service worker precaches).
writeFileSync('public/icon.svg', source);
console.log(`wrote public/icon.svg`);

for (const { out, size } of plain) {
  await sharp(Buffer.from(source)).resize(size, size).png().toFile(out);
  console.log(`wrote ${out} (${size}×${size})`);
}

for (const { out, size } of maskables) {
  await sharp(Buffer.from(maskable)).resize(size, size).png().toFile(out);
  console.log(`wrote ${out} (${size}×${size}, maskable, mark at ${MASKABLE_SCALE * 100}%)`);
}

// Browsers request /favicon.ico by default even when the page declares a PNG
// favicon; without this file that request 404s on every page load.
await sharp(Buffer.from(source)).resize(32, 32).toFile('public/favicon.ico');
console.log('wrote public/favicon.ico (32×32)');
